<script setup>
import { ref,computed,onMounted } from 'vue'
import { useTeaching,copy } from './useTeaching'
const props=defineProps({api:Function,teacher:Boolean})
const emit=defineEmits(['practice'])
const {busy,error,notice,request,all,run}=useTeaching(props.api)
const graphs=ref([]),questions=ref([]),selected=ref(null),form=ref(null),editing=ref(false),nodeId=ref(''),deleteConfirm=ref(false)
const data=computed(()=>form.value?.data||{nodes:[],edges:[]})
const activeNode=computed(()=>data.value.nodes.find(n=>n.id===nodeId.value))
const height=computed(()=>Math.max(320,Math.ceil(data.value.nodes.length/3)*120+60))
const positions=computed(()=>Object.fromEntries(data.value.nodes.map((n,i)=>[n.id,{x:120+(i%3)*230,y:75+Math.floor(i/3)*120}])))
const load=async()=>{graphs.value=await all('/graphs');questions.value=await all('/questions')}
function open(g){run(async()=>{form.value=copy(await request(`/graphs/${g.id}`));selected.value=g.id;editing.value=false;nodeId.value=form.value.data.nodes[0]?.id||'';deleteConfirm.value=false})}
function create(){selected.value=null;form.value={title:'',visibility:'private',data:{nodes:[],edges:[]}};editing.value=true;nodeId.value='';deleteConfirm.value=false;error.value=''}
function addNode(){form.value.data.nodes.push({id:'n_'+crypto.randomUUID().slice(0,8),label:'',description:'',questionIds:[]})}
function removeNode(index){const removed=form.value.data.nodes.splice(index,1)[0];form.value.data.edges=form.value.data.edges.filter(e=>e.source!==removed.id&&e.target!==removed.id)}
function save(){run(async()=>{const g=await request('/graphs'+(selected.value?'/'+selected.value:''),selected.value?'PUT':'POST',{title:form.value.title,visibility:form.value.visibility,data:form.value.data});form.value=copy(g);selected.value=g.id;editing.value=false;nodeId.value=g.data.nodes[0]?.id||'';await load()},'知识图谱已保存。')}
function remove(){run(async()=>{await request('/graphs/'+selected.value,'DELETE');selected.value=null;form.value=null;deleteConfirm.value=false;await load()},'知识图谱已删除。')}
onMounted(()=>run(load))
</script>
<template><section><div class="work-heading"><div><h2>知识图谱</h2><p>{{teacher?'连接知识点、前置关系与练习，构建课程知识结构。':'从知识关联出发，理解概念并进入相关练习。'}}</p></div><button v-if="teacher" class="work-primary" :disabled="busy" @click="create">新建图谱</button></div><p v-if="error" class="work-error" role="alert">{{error}}</p><p v-if="notice" class="work-notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理…</p><div class="work-grid"><div><div class="work-list"><button v-for="g in graphs" :key="g.id" :class="{active:selected===g.id}" :disabled="busy" @click="open(g)"><strong>{{g.title}}</strong><small>{{g.data.nodes.length}} 个知识点 · {{g.visibility==='public'?'公开':'仅自己可见'}}</small></button></div><p v-if="!graphs.length&&!busy" class="work-muted">暂无{{teacher?'':'公开'}}知识图谱。</p><button class="work-link work-footer" :disabled="busy" @click="run(load)">刷新图谱列表</button></div><div><template v-if="form"><form v-if="editing" class="work-card work-form" @submit.prevent="save"><fieldset :disabled="busy"><label>图谱名称<input v-model="form.title" required maxlength="150"/></label><label>可见范围<select v-model="form.visibility"><option value="private">仅自己可见</option><option value="public">向学生公开</option></select></label><div class="work-heading"><h3>知识点</h3><button type="button" class="work-button" :disabled="data.nodes.length>=100" @click="addNode">添加知识点</button></div><article v-for="(n,index) in data.nodes" :key="n.id" class="work-card work-form"><label>知识点名称<input v-model="n.label" required maxlength="100"/></label><label>概念说明<textarea v-model="n.description" maxlength="2000"/></label><label>关联题目（可多选）<select v-model="n.questionIds" multiple size="3"><option v-for="q in questions" :key="q.id" :value="q.id">{{q.title}}</option></select></label><p class="work-small">学生只会看到已公开的关联题目。</p><button type="button" class="work-danger" @click="removeNode(index)">移除此知识点</button></article><div class="work-heading"><h3>知识关系</h3><button type="button" class="work-button" :disabled="data.nodes.length<2||data.edges.length>=300" @click="data.edges.push({source:data.nodes[0].id,target:data.nodes[1].id,type:'prerequisite'})">添加关系</button></div><article v-for="(edge,index) in data.edges" :key="index" class="work-card work-form"><div class="work-row"><label>起点<select v-model="edge.source"><option v-for="n in data.nodes" :key="n.id" :value="n.id">{{n.label||'未命名知识点'}}</option></select></label><label>终点<select v-model="edge.target"><option v-for="n in data.nodes" :key="n.id" :value="n.id">{{n.label||'未命名知识点'}}</option></select></label></div><label>关系类型<select v-model="edge.type"><option value="prerequisite">起点是终点的前置知识</option><option value="related">相互关联</option></select></label><button type="button" class="work-button" @click="data.edges.splice(index,1)">移除关系</button></article><button class="work-primary">保存图谱</button></fieldset></form>
<template v-else><section class="work-card"><div class="work-heading"><h3>{{form.title}}</h3><div v-if="teacher" class="work-actions"><button class="work-button" :disabled="busy" @click="editing=true">编辑图谱</button><button class="work-danger" :disabled="busy" @click="deleteConfirm=true">删除</button></div></div><div v-if="deleteConfirm" class="work-error">确定删除该图谱？<button class="work-danger" :disabled="busy" @click="remove">确认删除</button><button :disabled="busy" @click="deleteConfirm=false">取消</button></div><p class="work-muted">点击知识点查看说明；实线箭头表示前置关系，虚线表示关联。</p><div v-if="data.nodes.length" class="graph-canvas"><svg :viewBox="`0 0 720 ${height}`" role="group" aria-label="课程知识关系图"><defs><marker id="graph-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#73a18c"/></marker></defs><g v-for="(e,index) in data.edges" :key="index"><path v-if="positions[e.source]&&positions[e.target]" :d="`M ${positions[e.source].x} ${positions[e.source].y+27} Q ${(positions[e.source].x+positions[e.target].x)/2} ${Math.max(positions[e.source].y,positions[e.target].y)+70} ${positions[e.target].x} ${positions[e.target].y+30}`" fill="none" stroke="#73a18c" stroke-width="2" :stroke-dasharray="e.type==='related'?'6 5':undefined" :marker-end="e.type==='prerequisite'?'url(#graph-arrow)':undefined"/></g><g v-for="n in data.nodes" :key="n.id" class="graph-node" tabindex="0" role="button" :aria-label="n.label" @click="nodeId=n.id" @keydown.enter.prevent="nodeId=n.id" @keydown.space.prevent="nodeId=n.id"><rect :x="positions[n.id].x-88" :y="positions[n.id].y-28" width="176" height="56" rx="12" :fill="nodeId===n.id?'#137c65':'#f0f7f3'" :stroke="nodeId===n.id?'#137c65':'#a6cbbb'"/><text :x="positions[n.id].x" :y="positions[n.id].y+5" text-anchor="middle" :fill="nodeId===n.id?'white':'#305c48'" font-size="15">{{n.label.length>10?n.label.slice(0,10)+'…':n.label}}</text><title>{{n.label}}</title></g></svg></div><p v-else>图谱还没有知识点。</p></section><section v-if="activeNode" class="work-card"><h3>{{activeNode.label}}</h3><p class="work-stem">{{activeNode.description||'暂未补充概念说明。'}}</p><div v-if="activeNode.questionIds.length"><p class="work-muted">关联练习：{{activeNode.questionIds.length}} 题</p><div v-if="!teacher" class="work-actions"><button v-for="(qid,index) in activeNode.questionIds" :key="qid" class="work-button" @click="emit('practice',qid)">{{index===0?'练习这个知识点':'关联练习 '+(index+1)}}</button></div><p v-else>{{activeNode.questionIds.map(id=>questions.find(q=>q.id===id)?.title||'原题已删除').join('、')}}</p></div><p v-else class="work-muted">暂未关联{{teacher?'':'公开'}}练习。</p><ul><li v-for="(edge,index) in data.edges.filter(e=>e.source===activeNode.id||e.target===activeNode.id)" :key="index">{{data.nodes.find(n=>n.id===edge.source)?.label}} {{edge.type==='prerequisite'?'→':'↔'}} {{data.nodes.find(n=>n.id===edge.target)?.label}}</li></ul></section></template></template><div v-else class="work-empty">{{teacher?'创建一张图谱，或选择已有图谱查看知识结构。':'选择一张知识图谱，探索知识点之间的联系。'}}</div></div></div></section></template>
<style scoped>.graph-canvas{overflow:auto;background:radial-gradient(circle,#dbeae1 1px,transparent 1px);background-size:18px 18px;border-radius:9px}.graph-canvas svg{display:block;width:100%;min-width:530px;max-height:800px}.graph-node{cursor:pointer}.graph-node:focus rect{stroke:#deaa4b;stroke-width:3}</style>
